  reset(): void { this.fresh = true; this.photo = false; this.phase = 0; this.w.fill(0); }

  /* Gỡ khỏi nhóm và bỏ mixer; geometry / texture / vật liệu thuộc nguồn dùng chung nên không dispose */
  dispose(): void {
    this.mixer.stopAllAction();
