// Chụp ảnh nhân vật có xương (Task 4, xem bằng mắt; không commit). node tests/screens/rig-shots.mjs
import { serveDir, launch, openApp } from '../lib.mjs';
import { fileURLToPath } from 'node:url';

const dist = fileURLToPath(new URL('../../dist/', import.meta.url));
const out = fileURLToPath(new URL('./', import.meta.url));
const srv = await serveDir(dist);
const browser = await launch();
const t0 = Date.now(), log = (m) => console.log(`[${((Date.now() - t0) / 1000).toFixed(0)} s] ${m}`);
try {
  const { page, errors } = await openApp(browser, srv.url + '?explore=stroll', { width: 960, height: 540 });
  page.on('console', (m) => { if (m.type() === 'warning' || m.type() === 'error') console.log('console:', m.type(), m.text()); });
  log('đã mở');
  await page.waitForFunction(() => window.__app.stroll.avatars.debug(0)?.real === true, null, { polling: 1000, timeout: 400000 });
  log('nhân vật thật đã nạp');
  // Tắt vòng điều khiển của chế độ (camera + bước chuyển động do script đặt)
  await page.evaluate(() => { const S = window.__app.stroll; S.stroll.update = () => {}; });

  /* Chạy n bước (dt 1/30) theo hướng yaw0 rồi đặt camera nhìn ngang người từ phía trước chếch (az: góc lệch so với hướng mặt) */
  const pose = (n, inp, az, dist, name) => page.evaluate(({ n, inp, az, dist }) => {
    const a = window.__app, S = a.stroll, s = S.stroll.state;
    const yaw0 = s.yaw;
    for (let i = 0; i < n; i++) S.stroll.step(1 / 30, { ...inp, camYaw: yaw0 });
    S.stroll.update = () => {};
    const c = a.camera, h = Math.cos(s.yaw + az), k = -Math.sin(s.yaw + az);   // hướng mặt (cos yaw, 0, −sin yaw)
    c.position.set(s.x + h * dist, s.y + 1.2, s.z + k * dist);
    a.controls.target.set(s.x, s.y + 0.95, s.z); c.lookAt(a.controls.target); c.updateMatrixWorld();
    const d = S.avatars.debug(S.avatars.self);
    let foot = null;
    S.avatars.mesh.traverse((o) => { if (o.name === 'Bip01_L_Foot' && o.parent && foot === null) { const v = new a.THREE.Vector3(); o.getWorldPosition(v); foot = v.y - s.y; } });
    return { x: s.x, y: s.y, z: s.z, yaw: s.yaw, speed: s.speed, pose: s.pose, air: s.air, real: d.real, mix: d.mix.map((v) => +v.toFixed(2)), rate: +d.rate.toFixed(2), footAbove: foot };
  }, { n, inp, az, dist });

  const shot = async (name, info) => {
    // camera do evaluate đặt; vòng animate vẽ lại khung kế
    await page.evaluate(() => new Promise((ok) => requestAnimationFrame(() => requestAnimationFrame(ok))));
    await page.screenshot({ path: out + name + '.png' });
    log(`${name}: ${JSON.stringify(info)}`);
  };

  const still = { mx: 0, mz: 0, run: false };
  let i = await pose(60, still, 0.6, 3.2); await shot('rig-idle', i);
  i = await pose(1, still, 1.57, 3.2); await shot('rig-idle-side', i);
  i = await pose(45, { mx: 0, mz: 1, run: false }, 1.57, 3.6); await shot('rig-jog', i);
  i = await pose(40, { mx: 0, mz: 1, run: true }, 1.57, 4.2); await shot('rig-sprint', i);
  i = await pose(40, still, 0.6, 3.2);
  await page.evaluate(() => window.__app.stroll.stroll.photo());
  i = await pose(15, still, 0.6, 3.2); await shot('rig-photo', i);
  i = await pose(40, still, 0.6, 3.2);
  await page.evaluate(() => { const d = window.__app.dayNight; d.target = 1; d.night = 1; });
  await page.waitForFunction(() => Math.abs(window.__app.dayNight.night - 1) < 1e-6, null, { polling: 1000, timeout: 120000 });
  i = await pose(1, still, 0.6, 3.2); await shot('rig-night', i);
  console.log('lỗi trang:', errors.length ? errors : 'không');
} finally { await browser.close(); srv.close(); }
